Archived ingestion instrumentation helper, unrelated to current task:
from collections import defaultdict


def summarize_ingestion(rows):
    counts = defaultdict(int)
    totals = defaultdict(float)
    for row in rows:
        label = str(row.get("operation", "unknown"))
        duration = max(0.0, float(row.get("elapsed_ms", 0)))
        counts[label] += 1
        totals[label] += duration
    return {label: {"count": count, "mean_ms": totals[label] / count}
            for label, count in sorted(counts.items())}


def export_ingestion(rows, minimum_count=2):
    summary = summarize_ingestion(rows)
    return [{"operation": name, **value}
            for name, value in summary.items()
            if value["count"] >= minimum_count]

